set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1
export GIT_OPTIONAL_LOCKS=0
cd /workspace/p2-4-compact-proof-20261125
python3 -B - <<'PY_SOLID_BOOTSTRAP'
import base64, gzip, hashlib, io, json, os, sys, tarfile
from pathlib import Path
packed = base64.b64decode('', validate=True)
assert len(packed) == 20964 and hashlib.sha256(packed).hexdigest() == '2fdc28c296204bf05b901b4bb3e7ce94ee01092b27ff11bf39fe324c486e7ef6'
raw = gzip.decompress(packed)
assert len(raw) == 92160 and hashlib.sha256(raw).hexdigest() == '3c02dafa2adada44d5cf91b5dde6b8c2b20289182054940196ef0cf276abca3c'
expected = json.loads('{"evidence-1087-blob.json":{"bytes":239,"sha256":"60b60bbac7d8d3dc7fc35e231f0463d46484e1cc34bdd2824fad4059afd89465"},"evidence-b55-blob.json":{"bytes":239,"sha256":"cd07ace0f3a594ffaced55036b666b936114c6c5ee1571afc6c18020d5319459"},"original-archive-1087-command.sh":{"bytes":6120,"sha256":"8f07c26f6a87cfbeb1bee3b0e6737793f67270af21215d4e4f56fec950fe6cff"},"original-archive-b55-command.sh":{"bytes":6393,"sha256":"5b1f9960c0d1fecb85e3072f2257456f227e9fd2670eef98141f6af6a9ba921a"},"restore_metadata.py":{"bytes":2439,"sha256":"efae202eaecaca6d47aec11b5a714b6b669cb44b3237dc180b041a3cae772590"},"retention-manifest.json":{"bytes":24180,"sha256":"d8ec23b6d0d2aca0ffc4f24abc4693c3df7f587f23336757c37417391d5af71a"},"retention_common.py":{"bytes":28410,"sha256":"796d76d331f0a01bf7791cd75f33d0e6b51740e4053425b86e248a9f96f332a4"},"stage1_preserve.py":{"bytes":5739,"sha256":"b4fcabf7ff805d541aa3e707ee28d18e96595b80ee8c195185d5369422a0e053"},"stage2_verify_release.py":{"bytes":10150,"sha256":"d831e348c40765a134af790e0b7a3a322c091dc2ab1d8fba420d6237475ed5ee"}}')
files = {}
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:') as archive:
    for member in archive:
        assert member.isfile() and member.name in expected and (member.name not in files)
        data = archive.extractfile(member).read()
        record = expected[member.name]
        assert len(data) == record['bytes'] and hashlib.sha256(data).hexdigest() == record['sha256']
        files[member.name] = data
assert set(files) == set(expected)
manifest = json.loads(files['retention-manifest.json'])
assert manifest['source_pin'] == 'b55fa93d39e6a4ddf2abd37b9b8481078e329f70'
directory = Path(manifest['scripts_dir'])
worktree = Path(manifest['worktree'])
assert str(directory) == '/workspace/p24-diagnostic-metadata-retention-20261126/scripts-002'
assert directory.resolve(strict=False) == directory and (not os.path.lexists(directory))
st = os.statvfs(worktree)
free_before = st.f_bavail * st.f_frsize
assert free_before >= manifest['reserve_bytes'] + manifest['max_control_files_bytes']
directory.mkdir(parents=True, exist_ok=False)
for name, data in files.items():
    with (directory / name).open('xb') as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    assert hashlib.sha256((directory / name).read_bytes()).hexdigest() == expected[name]['sha256']
for folder in [directory, directory.parent]:
    fd = os.open(folder, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)
st = os.statvfs(worktree)
free_after = st.f_bavail * st.f_frsize
assert free_after >= manifest['reserve_bytes']
print(json.dumps({'phase': 'draft02_script_deployment', 'script_files': len(files), 'payload_sha256': '2fdc28c296204bf05b901b4bb3e7ce94ee01092b27ff11bf39fe324c486e7ef6', 'free_before': free_before, 'free_after': free_after, 'observed_free_delta_bytes': free_after - free_before, 'canonical_credit': False}), flush=True)
os.execv(sys.executable, [sys.executable, '-B', str(directory / 'stage1_preserve.py')])
PY_SOLID_BOOTSTRAP
